interface Analytics {
  totalUsers: number;
  activeUsers: number;
  revenue: number;
}

interface Notification {
  id: number;
  message: string;
  type: string;
  read: boolean;
}

interface Settings {
  theme: string;
  language: string;
  notificationsEnabled: boolean;
}

async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then(r => r.json()),
      fetch('/api/notifications').then(r => r.json()),
      fetch('/api/settings').then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch {
    return {
      analytics: { totalUsers: 0, activeUsers: 0, revenue: 0 } as Analytics,
      notifications: [] as Notification[],
      settings: { theme: 'light', language: 'en', notificationsEnabled: true } as Settings
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Total Users: {analytics.totalUsers}</p>
        <p>Active Users: {analytics.activeUsers}</p>
        <p>Revenue: ${analytics.revenue}</p>
      </section>

      <section>
        <h3>Notifications ({notifications.length})</h3>
        <ul>
          {notifications.map((notification) => (
            <li key={notification.id}>
              {notification.message} ({notification.type})
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Language: {settings.language}</p>
        <p>Notifications: {settings.notificationsEnabled ? 'Enabled' : 'Disabled'}</p>
      </section>
    </div>
  );
}

